std::wstring sort_index(unsigned char i) {
	log(3, L"🔈sort_index");
	if (i == (unsigned char)0x00) return L"INTERNET_EXPLORER";
	if (i == (unsigned char)0x42) return L"LIBRARIES";
	if (i == (unsigned char)0x44) return L"USERS";
	if (i == (unsigned char)0x48) return L"MY_DOCUMENTS";
	if (i == (unsigned char)0x50) return L"MY_COMPUTER";
	if (i == (unsigned char)0x58) return L"MY_NETWORK_PLACES/NETWORK";
	if (i == (unsigned char)0x60) return L"RECYCLE BIN";
	if (i == (unsigned char)0x68) return L"INTERNET_EXPLORER";
	if (i == (unsigned char)0x70) return L"UNKNOWN";
	if (i == (unsigned char)0x80) return L"MY_GAMES";
	return L"UNKNOWN";
}

std::wstring shell_item_class(unsigned char i) {
	log(3, L"🔈shell_item_class");

	// 0x00, 0x79
	if (i == (unsigned char)0x00)  return L"USERS_PROPERTY_VIEW"; //done 
	if (i == (unsigned char)0x79)  return L"USERS_PROPERTY_VIEW"; //done 

	// 0x01
	if (i == (unsigned char)0x01)  return L"CONTROL_PANEL_CATEGORY"; //done

	/// 0x1F
	if (i == (unsigned char)0x1F)  return L"ROOT_FOLDER"; // done

	// 0x23, 0x25, 0x29, 0x2A, 0x2E, 0x2F
	if (i == (unsigned char)0x23)  return L"VOLUME_SHELL_ITEM"; //done
	if (i == (unsigned char)0x25)  return L"VOLUME_SHELL_ITEM"; //done
	if (i == (unsigned char)0x29)  return L"VOLUME_SHELL_ITEM"; //done
	if (i == (unsigned char)0x2A)  return L"VOLUME_SHELL_ITEM"; //done
	if (i == (unsigned char)0x2E)  return L"VOLUME_SHELL_ITEM"; //done
	if (i == (unsigned char)0x2F)  return L"VOLUME_SHELL_ITEM"; //done

	// 0x30, 0x31, 0x32, 0x35, 0x36, 0x39, 0xB1
	if (i == (unsigned char)0xB1)  return L"FILE_ENTRY_SHELL_ITEM"; //done
	if (i == (unsigned char)0x30)  return L"FILE_ENTRY_SHELL_ITEM"; //done
	if (i == (unsigned char)0x31)  return L"FILE_ENTRY_SHELL_ITEM"; //done
	if (i == (unsigned char)0x32)  return L"FILE_ENTRY_SHELL_ITEM"; //done
	if (i == (unsigned char)0x35)  return L"FILE_ENTRY_SHELL_ITEM"; //done
	if (i == (unsigned char)0x36)  return L"FILE_ENTRY_SHELL_ITEM"; //done
	if (i == (unsigned char)0x39)  return L"FILE_ENTRY_SHELL_ITEM"; //done

	// 0x41, 0x42, 0x46, 0x47, 0x4C, 0xC3
	if (i == (unsigned char)0xC3)  return L"NETWORK_LOCATION_SHELL_ITEM";//done
	if (i == (unsigned char)0x41)  return L"NETWORK_LOCATION_SHELL_ITEM";//done
	if (i == (unsigned char)0x42)  return L"NETWORK_LOCATION_SHELL_ITEM";//done
	if (i == (unsigned char)0x46)  return L"NETWORK_LOCATION_SHELL_ITEM";//done
	if (i == (unsigned char)0x47)  return L"NETWORK_LOCATION_SHELL_ITEM";//done
	if (i == (unsigned char)0x4C)  return L"NETWORK_LOCATION_SHELL_ITEM";//done

	// 0x52
	if (i == (unsigned char)0x52)  return L"ARCHIVE_FILE_CONTENT"; // done

	// 0x61
	if (i == (unsigned char)0x61) return L"URI";//done;

	// 0x71
	if (i == (unsigned char)0x71) return L"CONTROL_PANEL"; //done

	// 0x74
	if (i == (unsigned char)0x74) return L"USERS_FILES_FOLDER"; //done

	//0x78
	if (i == (unsigned char)0x78) return L"FAVORITE_SHELL_ITEM"; //done

	/* REPLI PAR MASQUE, comme le fait libfwsi (libfwsi_item.c).
	 *
	 * CE QUI MANQUAIT. Les tests ci-dessus énumèrent des valeurs EXACTES —
	 * 0x23, 0x25, 0x29… pour les volumes, 0x30, 0x31, 0x32, 0x35, 0x36, 0x39
	 * pour les entrées de fichier. Or le type d'un shell item se lit sur les
	 * bits 4 à 6 de l'octet de classe : libfwsi fait `class_type & 0x70` et
	 * traite d'un coup TOUTE la famille. WAC ne reconnaissait donc que 6 ou 7
	 * valeurs par famille sur 32, et classait « UNKNOWN » une entrée de fichier
	 * de classe 0x33, 0x3A ou 0xB2 — parfaitement décodable, et dont seuls les
	 * bits de poids faible (drapeaux) différaient.
	 *
	 * Les valeurs exactes sont conservées au-dessus : elles sont vérifiées, et
	 * certaines classes hors famille (0x1F, 0x52, 0x61, 0x71, 0x74, 0x78, 0x79)
	 * doivent primer sur le masque — d'où le fait que ce repli vienne en
	 * dernier. */
	switch (i & 0x70) {
	case 0x20: return L"VOLUME_SHELL_ITEM";
	case 0x30: return L"FILE_ENTRY_SHELL_ITEM";
	case 0x40: return L"NETWORK_LOCATION_SHELL_ITEM";
	default:   break;
	}

	return L"UNKNOWN";
}

std::wstring trans_guid_to_wstring(std::wstring guid) {
	log(3, L"🔈trans_guid_to_wstring");
	
	transform(guid.begin(), guid.end(), guid.begin(), ::tolower);

	// La table couvre CLSID, FMTID, dossiers spéciaux, AppID de périphériques…
	return chercher(TABLE_GUID, sizeof(TABLE_GUID)/sizeof(*TABLE_GUID), guid, indexGuid);
}
